style.css:
/* Saiyan Ascension — Google */

/* colors you can swap */
:root {
  --my-bg: #080d20;
  --my-blue: #142d58;
  --my-orange: #ff8c18;
  --my-gold: #ffd700;
  --my-text: #fff3d0;
}

/* dark cosmic atmosphere */
body {
  background-color: var(--my-bg) !important;
  background-image:
    radial-gradient(ellipse at 50% 35%,
      #284a78 0%,
      #14213f 38%,
      #080d20 85%) !important;
  color: var(--my-text) !important;
}

/* fiery links */
a {
  color: var(--my-gold) !important;
}

/* search field */
input {
  background: #111c35 !important;
  color: white !important;
  border: 1px solid var(--my-orange) !important;
  border-radius: 30px !important;
  box-shadow: 0 0 12px #ff8c1844 !important;
}

/* buttons */
button {
  background: linear-gradient(135deg, #ff9d24, #e65313) !important;
  color: white !important;
  border: 1px solid var(--my-gold) !important;
  border-radius: 20px !important;
  font-weight: bold !important;
  transition: 0.25s ease !important;
}

/* power-up hover */
button:hover {
  box-shadow: 0 0 18px var(--my-orange) !important;
  transform: translateY(-2px);
}

/* rounded shortcuts */
img {
  border-radius: 12px;
}

/* Google logo glow */
img[alt="Google"] {
  filter: drop-shadow(0 0 12px var(--my-gold)) !important;
}
